   Tokens
   ============================================================ */
:root {
  --bg-page:        #0d1117;
  --bg-card:        #161b22;
  --bg-input:       #0d1117;
  --border-default: #30363d;
  --border-focus:   #58a6ff;
  --border-error:   #f85149;

  --text-primary:   #e6edf3;
  --text-secondary: #8b949e;
  --text-error:     #f85149;
  --text-link:      #58a6ff;

  --accent:         #238636;
  --accent-hover:   #2ea043;

  --radius:         6px;
  --transition:     0.15s ease;
}

/* ============================================================
   Reset / Base
   ============================================================ */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

html {
  font-size: 100%;
  -webkit-text-size-adjust: 100%;
}

body {
  background-color: var(--bg-page);
  color: var(--text-primary);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica,
    Arial, sans-serif;
  line-height: 1.6;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

/* ============================================================
   Skip link
   ============================================================ */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  background: var(--bg-card);
  color: var(--text-link);
  padding: 0.5rem 1rem;
  border: 1px solid var(--border-focus);
  border-radius: var(--radius);
  text-decoration: none;
  font-size: 0.875rem;
  z-index: 100;
  transition: top var(--transition);
}

.skip-link:focus {
  top: 1rem;
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
}

/* ============================================================
   Site header
   ============================================================ */
.site-header {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 1rem 1.5rem;
  border-bottom: 1px solid var(--border-default);
  background: var(--bg-card);
}

.site-logo {
  font-size: 1.5rem;
  color: var(--text-link);
}

.site-name {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-primary);
}

/* ============================================================
   Main / layout
   ============================================================ */
main {
  flex: 1;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 2.5rem 1rem;
}

/* ============================================================
   Form card
   ============================================================ */
.form-card {
  background: var(--bg-card);
  border: 1px solid var(--border-default);
  border-radius: 10px;
  padding: 2rem 2.5rem;
  width: 100%;
  max-width: 540px;
}

.form-card h1 {
  font-size: 1.5rem;
  font-weight: 700;
  margin-bottom: 0.5rem;
  color: var(--text-primary);
}

.form-intro {
  color: var(--text-secondary);
  font-size: 0.9375rem;
  margin-bottom: 1.25rem;
}

.required-note {
  font-size: 0.8125rem;
  color: var(--text-secondary);
  margin-bottom: 1.5rem;
}

.required-note .required-star {
  color: var(--text-error);
  font-weight: 700;
  margin-right: 0.1em;
}

/* ============================================================
   Live-region containers (pre-rendered, always in DOM)
   ============================================================ */
.form-alert,
.form-status {
  /* hidden until content is inserted */
}

.form-alert:not(:empty),
.form-status:not(:empty) {
  display: block;
  padding: 0.75rem 1rem;
  border-radius: var(--radius);
  font-size: 0.9375rem;
  margin-bottom: 1.5rem;
}

.form-alert:not(:empty) {
  background: rgba(248, 81, 73, 0.12);
  border: 1px solid var(--border-error);
  color: var(--text-error);
}

.form-status:not(:empty) {
  background: rgba(35, 134, 54, 0.12);
  border: 1px solid #238636;
  color: #3fb950;
}

/* ============================================================
   Form fields
   ============================================================ */
form {
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
}

.form-field {
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
}

.form-field label {
  font-size: 0.9375rem;
  font-weight: 600;
  color: var(--text-primary);
  display: flex;
  align-items: baseline;
  gap: 0.2em;
}

.required-star {
  color: var(--text-error);
  font-size: 1em;
  line-height: 1;
}

.optional-tag {
  font-size: 0.8125rem;
  font-weight: 400;
  color: var(--text-secondary);
  margin-left: 0.25em;
}

.form-field input {
  background: var(--bg-input);
  border: 1px solid var(--border-default);
  border-radius: var(--radius);
  color: var(--text-primary);
  font-size: 0.9375rem;
  padding: 0.5625rem 0.75rem;
  width: 100%;
  transition: border-color var(--transition), box-shadow var(--transition);
  /* Ensure input is readable on autofill */
  color-scheme: dark;
}

.form-field input:hover {
  border-color: #8b949e;
}

.form-field input:focus {
  outline: 2px solid var(--border-focus);
  outline-offset: 0;
  border-color: var(--border-focus);
  box-shadow: 0 0 0 3px rgba(88, 166, 255, 0.15);
}

/* Error state */
.form-field input[aria-invalid="true"] {
  border-color: var(--border-error);
}

.form-field input[aria-invalid="true"]:focus {
  outline-color: var(--border-error);
  box-shadow: 0 0 0 3px rgba(248, 81, 73, 0.2);
}

/* ============================================================
   Help / error text
   ============================================================ */
.field-help {
  font-size: 0.8125rem;
  color: var(--text-secondary);
  line-height: 1.4;
}

.field-error {
  font-size: 0.8125rem;
  color: var(--text-error);
  line-height: 1.4;
}

.nowrap {
  white-space: nowrap;
}

/* ============================================================
   Submit button
   ============================================================ */
.btn-submit {
  margin-top: 0.5rem;
  background: var(--accent);
  color: #ffffff;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: var(--radius);
  font-size: 0.9375rem;
  font-weight: 600;
  padding: 0.625rem 1.25rem;
  cursor: pointer;
  align-self: flex-start;
  transition: background var(--transition), box-shadow var(--transition);
}

.btn-submit:hover {
  background: var(--accent-hover);
}

.btn-submit:focus-visible {
  outline: 2px solid var(--border-focus);
  outline-offset: 2px;
  box-shadow: 0 0 0 4px rgba(88, 166, 255, 0.2);
}

/* ============================================================
   Screen-reader only utility
   ============================================================ */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

/* ============================================================
   Forced colors (Windows high-contrast, etc.)
   ============================================================ */
@media (forced-colors: active) {
  .form-field input {
    border: 1px solid ButtonText;
  }

  .btn-submit {
    forced-color-adjust: none;
    background: ButtonFace;
    color: ButtonText;
    border: 2px solid ButtonText;
  }

  .form-alert:not(:empty),
  .form-status:not(:empty) {
    border: 1px solid CanvasText;
  }
}

/* ============================================================
   Reduced motion
   ============================================================ */
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }
}

/* ============================================================
   Reflow — narrow viewport (≥ 320 px)
   ============================================================ */
@media (max-width: 480px) {
  .form-card {
    padding: 1.5rem 1.25rem;
    border-radius: 8px;
  }

  .btn-submit {
    width: 100%;
    text-align: center;
  }
}
