 * On success a polite status live-region confirms submission.
 */

(function () {
  "use strict";

  /* ── field descriptors ─────────────────────────────────── */
  const FIELDS = [
    {
      id: "full-name",
      errorId: "full-name-error",
      required: true,
      validate(value) {
        if (!value.trim()) return "Error: Full name is required.";
        return null;
      },
    },
    {
      id: "email",
      errorId: "email-error",
      required: true,
      validate(value) {
        if (!value.trim()) return "Error: Email address is required.";
        // Basic structural check; the browser's type="email" handles more
        if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim()))
          return "Error: Enter a valid email address, e.g. name@example.com.";
        return null;
      },
    },
    {
      id: "phone",
      errorId: "phone-error",
      required: false,
      validate(value) {
        if (!value.trim()) return null; // optional
        // Accept international format with spaces/dashes/parens
        if (!/^\+?[\d\s\-().]{7,20}$/.test(value.trim()))
          return "Error: Enter a valid phone number, e.g. +1 555 000 1234.";
        return null;
      },
    },
  ];

  /* ── element references ────────────────────────────────── */
  const form       = document.getElementById("contact-form");
  const alertRegion  = document.getElementById("form-alert");
  const statusRegion = document.getElementById("form-status");

  /* ── helpers ───────────────────────────────────────────── */

  function getInput(field) {
    return document.getElementById(field.id);
  }

  function getError(field) {
    return document.getElementById(field.errorId);
  }

  /** Show an error on a field and mark it invalid. */
  function setFieldError(field, message) {
    const input = getInput(field);
    const error = getError(field);

    input.setAttribute("aria-invalid", "true");
    error.textContent = message;
    error.removeAttribute("hidden");
  }

  /** Clear the error on a field. */
  function clearFieldError(field) {
    const input = getInput(field);
    const error = getError(field);

    input.removeAttribute("aria-invalid");
    error.textContent = "";
    error.setAttribute("hidden", "");
  }

  /** Clear all field errors and live regions. */
  function clearAllErrors() {
    FIELDS.forEach(clearFieldError);
    alertRegion.textContent = "";
    statusRegion.textContent = "";
  }

  /* ── submit handler ────────────────────────────────────── */

  form.addEventListener("submit", function (event) {
    event.preventDefault();
    clearAllErrors();

    const errors = [];

    FIELDS.forEach(function (field) {
      const input = getInput(field);
      const message = field.validate(input.value);
      if (message) {
        errors.push({ field, message });
      }
    });

    if (errors.length > 0) {
      // Show individual field errors
      errors.forEach(function ({ field, message }) {
        setFieldError(field, message);
      });

      // Announce error count to screen readers via assertive live region
      const noun = errors.length === 1 ? "error" : "errors";
      alertRegion.textContent =
        errors.length +
        " " +
        noun +
        " prevented this form from being submitted. Please review the highlighted fields.";

      // Move focus to the first invalid field
      getInput(errors[0].field).focus();
      return;
    }

    // ── Simulate successful submission ──────────────────────
    // In a real app, POST the FormData here. We reset & confirm.
    form.reset();
    statusRegion.textContent =
      "Thank you! Your message has been sent. We'll be in touch soon.";
  });

  /* ── clear field error on user correction ──────────────── */
  FIELDS.forEach(function (field) {
    getInput(field).addEventListener("input", function () {
      if (this.getAttribute("aria-invalid") === "true") {
        const message = field.validate(this.value);
        if (!message) clearFieldError(field);
      }
    });
  });
