    return {
      label,
      wcag: wcag.map(v => ({ id: v.id, impact: v.impact, targets: v.nodes.map(n => n.target), failureSummary: v.nodes.map(n => n.failureSummary)[0] })),
      bp:   bp.map(v =>   ({ id: v.id, targets: v.nodes.map(n => n.target) })),
    };
  }

  const results = [summarise('initial', r1), summarise('error-state', r2)];
  console.log(JSON.stringify(results, null, 2));

  const anyWcag = results.some(r => r.wcag.length > 0);
  process.exit(anyWcag ? 1 : 0);
})();
